public class Main {

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

        int n = nextInt(in);
        int m = nextInt(in);
        int c = nextInt(in);

        // nxt[s] = musica amada do amigo mais antigo que detesta a musica s (0 se ninguem detesta s)
        int[] nxt = new int[m + 1];
        for (int i = 0; i < n; i++) {
            int a = nextInt(in);
            int d = nextInt(in);
            if (nxt[d] == 0) nxt[d] = a; // primeira ocorrencia (amigo mais antigo) define a transicao
        }

        boolean[] vis = new boolean[m + 1];
        int cur = c;
        vis[cur] = true;
        int cnt = 0;
        int ans;
        while (true) {
            int t = nxt[cur];
            if (t == 0) {          // ninguem detesta a musica atual -> todos satisfeitos
                ans = cnt;
                break;
            }
            cur = t;
            cnt++;
            if (vis[cur]) {        // estado repetido -> laco infinito
                ans = -1;
                break;
            }
            vis[cur] = true;
        }

        System.out.println(ans);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int b = in.read();
        while (b < '0' || b > '9') {
            if (b == -1) throw new EOFException();
            b = in.read();
        }
        int v = 0;
        while (b >= '0' && b <= '9') {
            v = v * 10 + (b - '0');
            b = in.read();
        }
        return v;
    }
}
